run_job() {
  local name="$1"; shift
  local log="$1"; shift
  echo "[$(date -Is)] START ${name}" | tee -a "$log"
  "$@" >> "$log" 2>&1
  local code=$?
  if [ $code -ne 0 ]; then
    echo "[$(date -Is)] RETRY ${name} after code ${code}" | tee -a "$log"
    "$@" >> "$log" 2>&1
    code=$?
  fi
  echo "[$(date -Is)] END ${name} code=${code}" | tee -a "$log"
  return 0
}
